        { s: "فِي أَمْوَالِكُمْ حَقٌّ لِفُقَرَائِكُمْ", a: "i", why: "Haber (<span class=\"ar\">فِي أَمْوَالِكُمْ</span>) öne geçmiş bir isim cümlesidir; mübtedâ <span class=\"ar\">حَقٌّ</span>." },
        { s: "يَسْأَلُكُمُ اللهُ يَوْمَ القِيَامَةِ عَنْ أَمْوَالِكُمْ", a: "f" },
        { s: "يَقُولُ اللهُ تَعَالَى فِي قُرْآنِهِ الكَرِيمِ", a: "f" },
        { s: "فِي مَالِ المُسْلِمِ حَقٌّ لِلْفَقِيرِ وَالمُحْتَاجِ", a: "i", why: "Haber öne geçmiş isim cümlesi; mübtedâ <span class=\"ar\">حَقٌّ</span>." }
